   377  igmpv3_group_record* IgmpV3ReportLayer::getNextGroupRecord(igmpv3_group_record* groupRecord) const
   378  {
   379          if (groupRecord == nullptr)
   380                  return nullptr;
   381
   382          // prev group was the last group
   383          if ((uint8_t*)groupRecord + groupRecord->getRecordLen() - m_Data >= (int)getHeaderLen())
   384                  return nullptr;
   385
   386          igmpv3_group_record* nextGroup = (igmpv3_group_record*)((uint8_t*)groupRecord + groupRecord->getRecordLen());
   387
   388          return nextGroup;
