   398  igmpv3_group_record* IgmpV3ReportLayer::addGroupRecordAt(uint8_t recordType, const IPv4Address& multicastAddress, const std::vector<IPv4Address>& sourceAddresses, int offset)
   399  {
   400          if (offset > (int)getHeaderLen())
   401          {
   402                  PCPP_LOG_ERROR("Cannot add group record, offset is out of layer bounds");
   403                  return nullptr;
   404          }
   405
   406          size_t groupRecordSize = sizeof(igmpv3_group_record) + sizeof(uint32_t)*sourceAddresses.size();
   407
   408          if (!extendLayer(offset, groupRecordSize))
   409          {
   410                  PCPP_LOG_ERROR("Cannot add group record, cannot extend layer");
   411                  return nullptr;
   412          }
   413
   414          uint8_t* groupRecordBuffer = new uint8_t[groupRecordSize];
   415          memset(groupRecordBuffer, 0, groupRecordSize);
   416          igmpv3_group_record* newGroupRecord = (igmpv3_group_record*)groupRecordBuffer;
   417          newGroupRecord->multicastAddress = multicastAddress.toInt();
   418          newGroupRecord->recordType = recordType;
   419          newGroupRecord->auxDataLen = 0;
   420          newGroupRecord->numOfSources = htobe16(sourceAddresses.size());
   421
   422          int srcAddrOffset = 0;
   423          for (std::vector<IPv4Address>::const_iterator iter = sourceAddresses.begin(); iter != sourceAddresses.end(); iter++)
   424          {
   425                  memcpy(newGroupRecord->sourceAddresses + srcAddrOffset, iter->toBytes(), sizeof(uint32_t));
   426                  srcAddrOffset += sizeof(uint32_t);
   427          }
   428
   429          memcpy(m_Data + offset, groupRecordBuffer, groupRecordSize);
   430
   431          delete[] groupRecordBuffer;
   432
   433          getReportHeader()->numOfGroupRecords = htobe16(getGroupRecordCount() + 1);
   434
   435          return (igmpv3_group_record*)(m_Data + offset);
   436  }
