   443  igmpv3_group_record* IgmpV3ReportLayer::addGroupRecordAtIndex(uint8_t recordType, const IPv4Address& multicastAddress, const std::vector<IPv4Address>& sourceAddresses, int index)
   444  {
   445          int groupCnt = (int)getGroupRecordCount();
   446
   447          if (index < 0 || index > groupCnt)
   448          {
   449                  PCPP_LOG_ERROR("Cannot add group record, index " << index << " out of bounds");
   450                  return nullptr;
   451          }
   452
   453          size_t offset = sizeof(igmpv3_report_header);
   454
   455          igmpv3_group_record* curRecord = getFirstGroupRecord();
   456          for (int i = 0; i < index; i++)
   457          {
   458                  if (curRecord == nullptr)
   459                  {
   460                          PCPP_LOG_ERROR("Cannot add group record, cannot find group record at index " << i);
   461                          return nullptr;
   462                  }
   463
   464                  offset += curRecord->getRecordLen();
   465                  curRecord = getNextGroupRecord(curRecord);
   466          }
   467
   468          return addGroupRecordAt(recordType, multicastAddress, sourceAddresses, (int)offset);
   469  }
