   471  bool IgmpV3ReportLayer::removeGroupRecordAtIndex(int index)
   472  {
   473          int groupCnt = (int)getGroupRecordCount();
   474
   475          if (index < 0 || index >= groupCnt)
   476          {
   477                  PCPP_LOG_ERROR("Cannot remove group record, index " << index << " is out of bounds");
   478                  return false;
   479          }
   480
   481          size_t offset = sizeof(igmpv3_report_header);
   482
   483          igmpv3_group_record* curRecord = getFirstGroupRecord();
   484          for (int i = 0; i < index; i++)
   485          {
   486                  if (curRecord == nullptr)
   487                  {
   488                          PCPP_LOG_ERROR("Cannot remove group record at index " << index << ", cannot find group record at index " << i);
   489                          return false;
   490                  }
   491
   492                  offset += curRecord->getRecordLen();
   493                  curRecord = getNextGroupRecord(curRecord);
   494          }
   495
   496          if (!shortenLayer((int)offset, curRecord->getRecordLen()))
   497          {
   498                  PCPP_LOG_ERROR("Cannot remove group record at index " << index << ", cannot shorted layer");
   499                  return false;
   500          }
   501
   502          getReportHeader()->numOfGroupRecords = htobe16(groupCnt-1);
   503
   504          return true;
   505  }
