   507  bool IgmpV3ReportLayer::removeAllGroupRecords()
   508  {
   509          int offset = (int)sizeof(igmpv3_report_header);
   510
   511          if (!shortenLayer(offset, getHeaderLen()-offset))
   512          {
   513                  PCPP_LOG_ERROR("Cannot remove all group records, cannot shorted layer");
   514                  return false;
   515          }
   516
   517          getReportHeader()->numOfGroupRecords = 0;
   518          return true;
   519  }
